-- Ordi Fatir (Ordi Fatir LLC, Khujand) -- demo database of a flour / pasta / feed producer in Tajikistan
-- FICTIONAL DATA generated for BI dashboard demos. Currency: TJS (somoni). Period: 2022-01-01 .. 2025-12-31.
-- Company profile (products, brands, facilities) is based on public information; customers, suppliers, people and all numbers are invented.
-- Safe to import into an empty MySQL schema.

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `expenses`;
DROP TABLE IF EXISTS `grain_purchases`;
DROP TABLE IF EXISTS `inventory`;
DROP TABLE IF EXISTS `quality_tests`;
DROP TABLE IF EXISTS `production_batches`;
DROP TABLE IF EXISTS `deliveries`;
DROP TABLE IF EXISTS `payments`;
DROP TABLE IF EXISTS `sales_order_items`;
DROP TABLE IF EXISTS `sales_orders`;
DROP TABLE IF EXISTS `customers`;
DROP TABLE IF EXISTS `drivers`;
DROP TABLE IF EXISTS `vehicles`;
DROP TABLE IF EXISTS `employees`;
DROP TABLE IF EXISTS `departments`;
DROP TABLE IF EXISTS `warehouses`;
DROP TABLE IF EXISTS `facilities`;
DROP TABLE IF EXISTS `receiving_points`;
DROP TABLE IF EXISTS `suppliers`;
DROP TABLE IF EXISTS `grain_types`;
DROP TABLE IF EXISTS `products`;
DROP TABLE IF EXISTS `product_categories`;
DROP TABLE IF EXISTS `regions`;

CREATE TABLE `regions` (
    `region_id` INT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL,
    `center_city` VARCHAR(80) NOT NULL,
    `country` VARCHAR(60) NOT NULL,
    `distance_from_plant_km` INT NOT NULL,
    `is_export` TINYINT(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `product_categories` (
    `category_id` INT PRIMARY KEY,
    `name` VARCHAR(80) NOT NULL,
    `description` VARCHAR(255) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `products` (
    `product_id` INT PRIMARY KEY,
    `sku` VARCHAR(12) NOT NULL UNIQUE,
    `name` VARCHAR(150) NOT NULL,
    `category_id` INT NOT NULL,
    `brand` VARCHAR(30) NOT NULL,
    `grade` VARCHAR(40) NULL,
    `pack_size_kg` DECIMAL(8,2) NOT NULL,
    `unit_cost_tjs` DECIMAL(10,2) NOT NULL,
    `unit_price_tjs` DECIMAL(10,2) NOT NULL,
    `launched_date` DATE NOT NULL,
    `is_active` TINYINT(1) NOT NULL,
    FOREIGN KEY (`category_id`) REFERENCES `product_categories`(`category_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `grain_types` (
    `grain_type_id` INT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL,
    `species` ENUM('wheat','durum','rye','barley','corn') NOT NULL,
    `grade_class` VARCHAR(10) NOT NULL,
    `standard` VARCHAR(30) NOT NULL,
    `min_protein_pct` DECIMAL(4,1) NOT NULL,
    `reference_price_tjs_per_ton` DECIMAL(10,2) NOT NULL,
    `used_for` ENUM('flour','pasta_semolina','feed') NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `suppliers` (
    `supplier_id` INT PRIMARY KEY,
    `name` VARCHAR(150) NOT NULL,
    `country` VARCHAR(60) NOT NULL,
    `region` VARCHAR(100) NOT NULL,
    `supplier_type` ENUM('elevator','trader','farm','cooperative','own_farm') NOT NULL,
    `contact_person` VARCHAR(100) NOT NULL,
    `phone` VARCHAR(25) NOT NULL,
    `contract_start_date` DATE NOT NULL,
    `payment_terms_days` INT NOT NULL,
    `quality_rating` DECIMAL(2,1) NOT NULL,
    `is_active` TINYINT(1) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `receiving_points` (
    `point_id` INT PRIMARY KEY,
    `name` VARCHAR(120) NOT NULL,
    `address` VARCHAR(200) NOT NULL,
    `city` VARCHAR(60) NOT NULL,
    `capacity_tons` INT NOT NULL,
    `has_dryer` TINYINT(1) NOT NULL,
    `opened_date` DATE NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `facilities` (
    `facility_id` INT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL,
    `facility_type` ENUM('flour_mill','pasta_plant','feed_mill','elevator') NOT NULL,
    `city` VARCHAR(60) NOT NULL,
    `capacity_tons_per_day` INT NOT NULL,
    `commissioned_date` DATE NOT NULL,
    `status` ENUM('operating','maintenance','planned') NOT NULL,
    `description` VARCHAR(255) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `warehouses` (
    `warehouse_id` INT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL,
    `region_id` INT NOT NULL,
    `city` VARCHAR(60) NOT NULL,
    `capacity_tons` INT NOT NULL,
    `opened_date` DATE NOT NULL,
    FOREIGN KEY (`region_id`) REFERENCES `regions`(`region_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `departments` (
    `department_id` INT PRIMARY KEY,
    `name` VARCHAR(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `employees` (
    `employee_id` INT PRIMARY KEY,
    `first_name` VARCHAR(50) NOT NULL,
    `last_name` VARCHAR(60) NOT NULL,
    `gender` ENUM('M','F') NOT NULL,
    `department_id` INT NOT NULL,
    `facility_id` INT NULL,
    `position` VARCHAR(80) NOT NULL,
    `hire_date` DATE NOT NULL,
    `termination_date` DATE NULL,
    `status` ENUM('active','on_leave','terminated') NOT NULL,
    `salary_tjs` DECIMAL(10,2) NOT NULL,
    `email` VARCHAR(120) NOT NULL,
    `phone` VARCHAR(25) NOT NULL,
    FOREIGN KEY (`department_id`) REFERENCES `departments`(`department_id`),
    FOREIGN KEY (`facility_id`) REFERENCES `facilities`(`facility_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `vehicles` (
    `vehicle_id` INT PRIMARY KEY,
    `plate_number` VARCHAR(15) NOT NULL UNIQUE,
    `make` VARCHAR(40) NOT NULL,
    `model` VARCHAR(40) NOT NULL,
    `vehicle_type` ENUM('bulk_flour_truck','flatbed_truck','semi_trailer','van') NOT NULL,
    `capacity_tons` DECIMAL(5,1) NOT NULL,
    `year_manufactured` YEAR NOT NULL,
    `purchase_date` DATE NOT NULL,
    `base_warehouse_id` INT NOT NULL,
    `fuel_l_per_100km` DECIMAL(5,1) NOT NULL,
    `status` ENUM('active','maintenance','retired') NOT NULL,
    FOREIGN KEY (`base_warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `drivers` (
    `driver_id` INT PRIMARY KEY,
    `employee_id` INT NOT NULL UNIQUE,
    `license_category` ENUM('C','CE','C+E') NOT NULL,
    `license_expiry_date` DATE NOT NULL,
    `experience_years` INT NOT NULL,
    FOREIGN KEY (`employee_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `customers` (
    `customer_id` INT PRIMARY KEY,
    `name` VARCHAR(150) NOT NULL,
    `segment` ENUM('distributor','wholesaler','supermarket','bakery','horeca','retail_shop','poultry_farm','livestock_farm','export_partner') NOT NULL,
    `region_id` INT NOT NULL,
    `city` VARCHAR(80) NOT NULL,
    `address` VARCHAR(200) NOT NULL,
    `phone` VARCHAR(25) NOT NULL,
    `registered_date` DATE NOT NULL,
    `credit_limit_tjs` DECIMAL(12,2) NOT NULL,
    `payment_terms_days` INT NOT NULL,
    `account_manager_id` INT NOT NULL,
    `customer_tier` ENUM('A','B','C') NOT NULL,
    `is_active` TINYINT(1) NOT NULL,
    FOREIGN KEY (`region_id`) REFERENCES `regions`(`region_id`),
    FOREIGN KEY (`account_manager_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `sales_orders` (
    `order_id` INT PRIMARY KEY,
    `order_number` VARCHAR(20) NOT NULL UNIQUE,
    `customer_id` INT NOT NULL,
    `warehouse_id` INT NOT NULL,
    `order_date` DATE NOT NULL,
    `required_date` DATE NOT NULL,
    `status` ENUM('processing','shipped','delivered','cancelled') NOT NULL,
    `channel` ENUM('phone','sales_visit','whatsapp','portal') NOT NULL,
    `delivery_type` ENUM('own_fleet','third_party','pickup') NOT NULL,
    `payment_terms_days` INT NOT NULL,
    `payment_status` ENUM('paid','partial','unpaid','overdue') NOT NULL,
    `total_weight_tons` DECIMAL(10,3) NOT NULL,
    `discount_tjs` DECIMAL(14,2) NOT NULL,
    `total_amount_tjs` DECIMAL(14,2) NOT NULL,
    `account_manager_id` INT NOT NULL,
    FOREIGN KEY (`customer_id`) REFERENCES `customers`(`customer_id`),
    FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`),
    FOREIGN KEY (`account_manager_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `sales_order_items` (
    `item_id` INT PRIMARY KEY,
    `order_id` INT NOT NULL,
    `product_id` INT NOT NULL,
    `quantity_units` INT NOT NULL,
    `unit_price_tjs` DECIMAL(10,2) NOT NULL,
    `discount_pct` DECIMAL(5,2) NOT NULL,
    `line_total_tjs` DECIMAL(14,2) NOT NULL,
    `weight_tons` DECIMAL(10,3) NOT NULL,
    FOREIGN KEY (`order_id`) REFERENCES `sales_orders`(`order_id`),
    FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `payments` (
    `payment_id` INT PRIMARY KEY,
    `order_id` INT NOT NULL,
    `payment_date` DATE NOT NULL,
    `amount_tjs` DECIMAL(14,2) NOT NULL,
    `method` ENUM('bank_transfer','cash','card','mobile_wallet') NOT NULL,
    `reference_number` VARCHAR(25) NOT NULL,
    FOREIGN KEY (`order_id`) REFERENCES `sales_orders`(`order_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `deliveries` (
    `delivery_id` INT PRIMARY KEY,
    `order_id` INT NOT NULL,
    `delivery_type` ENUM('own_fleet','third_party','pickup') NOT NULL,
    `vehicle_id` INT NULL,
    `driver_id` INT NULL,
    `dispatch_date` DATE NOT NULL,
    `delivery_date` DATE NOT NULL,
    `status` ENUM('scheduled','in_transit','delivered') NOT NULL,
    `distance_km` INT NOT NULL,
    `load_tons` DECIMAL(10,3) NOT NULL,
    `trucks_used` INT NOT NULL,
    `fuel_liters` DECIMAL(9,1) NOT NULL,
    `delivery_cost_tjs` DECIMAL(12,2) NOT NULL,
    `delay_hours` INT NOT NULL,
    `customer_rating` TINYINT NULL,
    FOREIGN KEY (`order_id`) REFERENCES `sales_orders`(`order_id`),
    FOREIGN KEY (`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`),
    FOREIGN KEY (`driver_id`) REFERENCES `drivers`(`driver_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `production_batches` (
    `batch_id` INT PRIMARY KEY,
    `batch_code` VARCHAR(24) NOT NULL UNIQUE,
    `facility_id` INT NOT NULL,
    `product_id` INT NULL,
    `run_type` ENUM('finished_goods','intermediate') NOT NULL,
    `production_date` DATE NOT NULL,
    `shift` ENUM('day','night') NOT NULL,
    `supervisor_id` INT NOT NULL,
    `input_tons` DECIMAL(10,3) NOT NULL,
    `output_tons` DECIMAL(10,3) NOT NULL,
    `by_product_tons` DECIMAL(10,3) NOT NULL,
    `yield_pct` DECIMAL(5,2) NOT NULL,
    `units_produced` INT NOT NULL,
    `downtime_minutes` INT NOT NULL,
    `energy_kwh` DECIMAL(10,1) NOT NULL,
    `defect_pct` DECIMAL(5,2) NOT NULL,
    FOREIGN KEY (`facility_id`) REFERENCES `facilities`(`facility_id`),
    FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`),
    FOREIGN KEY (`supervisor_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `quality_tests` (
    `test_id` INT PRIMARY KEY,
    `batch_id` INT NOT NULL,
    `tested_at` DATETIME NOT NULL,
    `tester_id` INT NOT NULL,
    `moisture_pct` DECIMAL(4,1) NOT NULL,
    `protein_pct` DECIMAL(4,1) NOT NULL,
    `gluten_pct` DECIMAL(4,1) NULL,
    `ash_pct` DECIMAL(4,2) NULL,
    `result` ENUM('passed','passed_with_remarks','failed') NOT NULL,
    FOREIGN KEY (`batch_id`) REFERENCES `production_batches`(`batch_id`),
    FOREIGN KEY (`tester_id`) REFERENCES `employees`(`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `inventory` (
    `inventory_id` INT PRIMARY KEY,
    `snapshot_date` DATE NOT NULL,
    `warehouse_id` INT NOT NULL,
    `product_id` INT NOT NULL,
    `quantity_units` INT NOT NULL,
    `quantity_tons` DECIMAL(10,3) NOT NULL,
    `reorder_level_units` INT NOT NULL,
    `stock_value_tjs` DECIMAL(14,2) NOT NULL,
    FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`),
    FOREIGN KEY (`product_id`) REFERENCES `products`(`product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `grain_purchases` (
    `purchase_id` INT PRIMARY KEY,
    `supplier_id` INT NOT NULL,
    `grain_type_id` INT NOT NULL,
    `receiving_point_id` INT NOT NULL,
    `purchase_date` DATE NOT NULL,
    `quantity_tons` DECIMAL(10,3) NOT NULL,
    `price_per_ton_tjs` DECIMAL(10,2) NOT NULL,
    `total_cost_tjs` DECIMAL(14,2) NOT NULL,
    `protein_pct` DECIMAL(4,1) NOT NULL,
    `moisture_pct` DECIMAL(4,1) NOT NULL,
    `impurity_pct` DECIMAL(4,1) NOT NULL,
    `transport_mode` ENUM('truck','rail') NOT NULL,
    `payment_status` ENUM('paid','pending') NOT NULL,
    FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`supplier_id`),
    FOREIGN KEY (`grain_type_id`) REFERENCES `grain_types`(`grain_type_id`),
    FOREIGN KEY (`receiving_point_id`) REFERENCES `receiving_points`(`point_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE `expenses` (
    `expense_id` INT PRIMARY KEY,
    `expense_month` DATE NOT NULL,
    `category` ENUM('raw_materials','electricity','packaging','salaries','maintenance','fuel','third_party_freight','marketing','taxes_and_fees','administrative','certification_and_lab') NOT NULL,
    `facility_id` INT NULL,
    `department_id` INT NULL,
    `amount_tjs` DECIMAL(14,2) NOT NULL,
    `description` VARCHAR(200) NULL,
    FOREIGN KEY (`facility_id`) REFERENCES `facilities`(`facility_id`),
    FOREIGN KEY (`department_id`) REFERENCES `departments`(`department_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


















































































































































































































































































SET FOREIGN_KEY_CHECKS = 1;
